var VLEX="be have do say get make go know take see come think look want give use find tell ask work seem feel try leave call need become keep let begin help talk turn start show hear play run move like live believe hold bring happen thank invite join order rent hire fly drive ride sail camp hike shop save pack forget carry pick choose check send enjoy cook clean wash teach study finish practise practice share sing dance paint draw wear write provide sit stand lose pay meet include continue set learn change lead understand watch follow stop create speak read allow add spend grow open walk win offer remember love consider appear buy wait serve die send expect build stay fall cut reach kill remain suggest raise pass sell require report decide pull travel visit enjoy relax swim climb explore eat drink sleep arrive book cost rain snow cook taste smell sound hope plan prefer agree mean wish visit".split(" ");
var VSET={}; VLEX.forEach(function(v){VSET[v]=1;});
function isVerbish(w){
  w=w.toLowerCase().replace(/’/g,"'");
  if(/^(am|is|are|was|were|be|been|being|have|has|had|do|does|did|will|would|can|could|should|must|may|might|shall|ought)$/.test(w)) return true;
  if(/'(m|s|re|ve|ll|d)$|n't$/.test(w)) return true;
  if(VSET[w]) return true; var b=toBase(w); if(VSET[b]) return true;
  if(/ed$/.test(w)&&w.length>4) return true; if(/ing$/.test(w)&&w.length>5) return true;
  var irr={went:1,saw:1,came:1,took:1,made:1,got:1,ate:1,gave:1,knew:1,thought:1,told:1,found:1,bought:1,spent:1,ran:1,wrote:1,said:1,met:1,left:1,felt:1,kept:1,paid:1,sat:1,stood:1,lost:1,heard:1,brought:1,flew:1,drove:1,slept:1,swam:1,began:1,became:1,held:1,sold:1,taught:1,caught:1};
  return !!irr[w];
}
/* extra checks that run on top of the rules: spelling, and sentences where nothing else was flagged */
function extraIssues(text, mode, hits){
  var out=[], m;
  if(mode!=="voice"){
    var re=/[A-Za-z’']+/g;
    while((m=re.exec(text))){
      var w=m[0], lw=w.toLowerCase();
      if(lw.length<3||/^['’]/.test(w)) continue;
      var s=m.index, e=s+w.length;
      if(hits.some(function(h){return s<h.e&&e>h.s;})) continue;
      var prev=text.slice(0,s).replace(/[\s"“(]+$/,""), sentStart=(prev===""||/[.!?]$/.test(prev));
      if(/^[A-Z]/.test(w) && !sentStart) continue;
      if(/^[A-Z]{2,}$/.test(w)) continue;
      if(known(lw)) continue;
      if(CAPS[lw]) continue;
      if(/^[A-Z]/.test(w)){ var e1c=edits1(lw).filter(function(x){return x.length>2&&dictHas(x);}); if(!e1c.length) continue; }
      var sg=suggest(lw);
      out.push({s:s,e:e,t:E,fix:sg.length?sg.join(" / "):"(check the spelling)",why:sg.length?"spelling: this is not an English word. Did you mean…?":"spelling: I cannot find this word in the dictionary"});
    }
  }
  /* sentence level */
  var sre=/[^.!?\n]+[.!?]*/g, ss;
  while((ss=sre.exec(text))){
    var seg=ss[0], base=ss.index, trimmed=seg.trim(); if(!trimmed) continue;
    var st=base+seg.indexOf(trimmed[0]), en=st+trimmed.length;
    var ws=trimmed.match(/[A-Za-z’']+/g)||[];
    if(ws.length<2) continue;
    var inside=hits.concat(out).some(function(h){return h.s<en&&h.e>st;});
    if(inside) continue;
    var fw=ws[0], fe=st+fw.length;
    if(false && ws.length>=5 && !/^(dear|hi|hello|hey|best|kind|yours|love|regards|thanks|cheers|sincerely)$/i.test(fw) && !ws.some(isVerbish)){
      out.push({s:st,e:fe,t:C,fix:"(add a verb)",why:"I cannot find a verb in this sentence — every sentence needs one (is / are / go / like…). Check that it is complete."});
    } else if(/^(because|although|though|while|whereas|since)$/i.test(fw) && ws.length<=7 && !/,/.test(trimmed) && mode!=="voice"){
      out.push({s:st,e:fe,t:C,fix:"(join to the main sentence)",why:"a sentence starting with “"+fw.toLowerCase()+"” needs a main clause: “…, because …” or “Because …, I …”."});
    } else if(ws.length>=34 && (trimmed.match(/\b(and|but|so)\b/gi)||[]).length>=3 && mode!=="voice"){
      out.push({s:st,e:fe,t:S,fix:"(split into two sentences)",why:"this sentence is very long ("+ws.length+" words) and joins many ideas with and / but / so."});
    }
  }
  return out;
}

function findIssuesBase(text, mode){
  var hits=[];
  RULES.forEach(function(r){
    if (r.w && mode==="voice") return;
    var fl=r.re.flags; if(fl.indexOf("g")<0) fl+="g";
    var re=new RegExp(r.re.source,fl), m;
    while((m=re.exec(text))){
      if(m[0]==="") { re.lastIndex++; continue; }
      var fx=(typeof r.fix==="function")?r.fix(m):r.fix;
      if (fx===undefined||fx===null) continue;
      if (r.t===E && typeof fx==="string" && fx===m[0] && r.re.source.indexOf("\\1")<0) continue;
      hits.push({s:m.index,e:m.index+m[0].length,t:r.t,fix:fx,why:r.why,mask:r.mask});
    }
  });
  hits.sort(function(a,b){return a.s-b.s||(b.e-b.s)-(a.e-a.s);});
  var out=[],end=-1;
  hits.forEach(function(h){ if(h.s>=end){out.push(h);end=h.e;} });
  return out;
}
function findIssuesNoS(text){
  var hits=[];
  RULES.forEach(function(r){ if(r.t===S) return; var fl=r.re.flags; if(fl.indexOf("g")<0) fl+="g"; var re=new RegExp(r.re.source,fl), m;
    while((m=re.exec(text))){ if(m[0]===""){ re.lastIndex++; continue; } var fx=(typeof r.fix==="function")?r.fix(m):r.fix; if(fx===undefined||fx===null) continue;
      if(r.t===E && typeof fx==="string" && fx===m[0] && r.re.source.indexOf("\\1")<0) continue; hits.push({s:m.index,e:m.index+m[0].length,t:r.t,fix:fx,why:r.why,mask:r.mask}); } });
  hits.sort(function(a,b){return a.s-b.s||(b.e-b.s)-(a.e-a.s);}); var base=[],end=-1; hits.forEach(function(h){ if(h.s>=end){base.push(h);end=h.e;} });
  var ex=extraIssues(text,"typed",base).filter(function(i){return i.t!==S;});
  var all=base.concat(ex); all.sort(function(a,b){return a.s-b.s||(b.e-b.s)-(a.e-a.s);});
  var out=[]; end=-1; all.forEach(function(h){ if(h.s>=end){out.push(h);end=h.e;} }); return out;
}
function findIssues(text, mode){
  var base=findIssuesBase(text,mode), ex=extraIssues(text,mode,base);
  var all=base.concat(ex); all.sort(function(a,b){return a.s-b.s||(b.e-b.s)-(a.e-a.s);});
  var out=[],end=-1; all.forEach(function(h){ if(h.s>=end){out.push(h);end=h.e;} }); return out;
}
function chunkHighlight(seg){
  var h=esc(seg);
  CHUNKS.forEach(function(c){ h=h.replace(new RegExp(c[1].source,"gi"),function(x){return "<mark class='okw'>"+x+"</mark>";}); });
  return h.replace(/<mark class='okw'><mark class='okw'>/g,"<mark class='okw'>").replace(/<\/mark><\/mark>/g,"</mark>");
}
function render(text,issues){
  var html="",p=0;
  issues.forEach(function(i){
    html+=chunkHighlight(text.slice(p,i.s));
    var w=text.slice(i.s,i.e); if(i.mask) w=w[0]+new Array(w.length).join("*");
    var label={err:"✗",chk:"?",sty:"tip"}[i.t];
    html+='<u class="'+i.t+'">'+esc(w)+'</u><span class="fx '+i.t+'">['+label+' '+esc(i.fix)+' — '+esc(i.why)+']</span>';
    p=i.e;
  });
  return html+chunkHighlight(text.slice(p));
}
function words(t){ return (t.match(/[A-Za-z’']+/g)||[]).length; }
function used(t){ return CHUNKS.filter(function(c){return c[1].test(t);}).map(function(c){return c[0];}); }
function half(x){ return Math.round(x*2)/2; }
function clip(x,a,b){ return Math.max(a,Math.min(b,x)); }
function sentences(t){ return t.split(/(?<=[.!?])\s+/).filter(function(s){return s.trim();}); }

